
select "PURCHASE_ACTIVITY_MEASURE"."BRANCH_PLANT" "Branch_Plant", "PURCHASE_ACTIVITY"."PO_NUMBER" "PO_Number", "PURCHASE_ACTIVITY_MEASURE"."LINE_NUMBER" "Line_Number", "ITEM"."ITEM_NUMBER_2ND" "C_2nd_Item_Number", "PURCHASE_ACTIVITY_MEASURE"."PO_DATE" "PO_Date", "PURCHASE_ACTIVITY"."REQUESTED_DATE" "Requested_Date", "PURCHASE_ACTIVITY"."PROMISED_DATE" "Promised_Date", "PURCHASE_ACTIVITY"."PO_DETAIL_CLOSED_DATE" "Receipt_Date", "PURCHASE_ACTIVITY_MEASURE"."VENDOR_ID" "Vendor_ID", "VENDOR"."VENDOR_NAME" "Vendor_Name", "ITEM"."LEADTIME_LEVEL_" "Lead_Time_Level", sum("PURCHASE_ACTIVITY_MEASURE"."QUANTITY_CANCELLED") "Quantity_Cancelled", sum("PURCHASE_ACTIVITY_MEASURE"."PO_QUANTITY_ORDERED"*"PURCHASE_ACTIVITY_MEASURE"."CONVERSION_FACTOR_LB") "PO_Quantity_Ordered_LBs", sum("PURCHASE_ACTIVITY_MEASURE"."OPEN_QUANTITY") "Open_Quantity", sum("PURCHASE_ACTIVITY_MEASURE"."OPEN_QUANTITY"*"PURCHASE_ACTIVITY_MEASURE"."CONVERSION_FACTOR_LB") "Open_Quantity_LBs", sum("PURCHASE_ACTIVITY_MEASURE"."SPEND_AMOUNT"*"T5"."FROM_TO_EXCHANGE_RATE") "Spend_Amount_USD", sum("PURCHASE_ACTIVITY_MEASURE"."PURCHASE_AMOUNT"*"T5"."FROM_TO_EXCHANGE_RATE") "Purchase_Amount_USD"
 from "DW_LEGACY"."PURCHASE_ACTIVITY_MEASURES" "PURCHASE_ACTIVITY_MEASURE", "DW_LEGACY"."PURCHASE_ACTIVITY" "PURCHASE_ACTIVITY", "DW_LEGACY"."ITEM" "ITEM", "DW_LEGACY"."VENDOR" "VENDOR", "DW_LEGACY"."FIN_CURRENCY_CONVERSION" "T5"
 where "PURCHASE_ACTIVITY"."PROMISED_DATE">=to_date(sysdate) - 365 and "PURCHASE_ACTIVITY_MEASURE"."BRANCH_PLANT" in (N'CINC', N'CIN2', N'CIN4') and "PURCHASE_ACTIVITY"."PO_DOCUMENT_TYPE" in (N'OP', N'OD') and "T5"."FROM_CURRENCY_CODE"="PURCHASE_ACTIVITY_MEASURE"."MONETARY_CURRENCY_CODE" and "T5"."TO_CURRENCY_CODE"='USD' and "T5"."RATE_TYPE_CODE"='M' and "PURCHASE_ACTIVITY_MEASURE"."PO_DATE">="T5"."EFFECTIVE_START_DATE" and "PURCHASE_ACTIVITY_MEASURE"."PO_DATE"<="T5"."EFFECTIVE_END_DATE" and "PURCHASE_ACTIVITY"."PURCHASE_ACTIVITY_SID"="PURCHASE_ACTIVITY_MEASURE"."PURCHASE_ACTIVITY_SID" and "PURCHASE_ACTIVITY_MEASURE"."PURCHASE_ACTIVITY__ITEM_SID"="ITEM"."ITEM_SID" and "PURCHASE_ACTIVITY_MEASURE"."VENDOR_SID"="VENDOR"."VENDOR_SID"
 group by "PURCHASE_ACTIVITY_MEASURE"."BRANCH_PLANT", "PURCHASE_ACTIVITY"."PO_NUMBER", "PURCHASE_ACTIVITY_MEASURE"."LINE_NUMBER", "ITEM"."ITEM_NUMBER_2ND", "PURCHASE_ACTIVITY"."PROMISED_DATE", "PURCHASE_ACTIVITY_MEASURE"."PO_DATE", "PURCHASE_ACTIVITY"."REQUESTED_DATE", "PURCHASE_ACTIVITY"."PO_DETAIL_CLOSED_DATE", "PURCHASE_ACTIVITY_MEASURE"."VENDOR_ID", "VENDOR"."VENDOR_NAME", "ITEM"."LEADTIME_LEVEL_"
 order by "PO_Number" asc nulls last, "Line_Number" asc nulls last



